ALTER POLICY invoice_insert ON public.officeai_invoices WITH CHECK (EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id=officeai_invoices.organization_id AND m.user_id=(SELECT auth.uid()) AND m.role='owner'));
ALTER POLICY invoice_update ON public.officeai_invoices USING (EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id=officeai_invoices.organization_id AND m.user_id=(SELECT auth.uid()) AND m.role='owner')) WITH CHECK (EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id=officeai_invoices.organization_id AND m.user_id=(SELECT auth.uid()) AND m.role='owner'));
